import json
from azure.ai.documentintelligence import DocumentAnalysisClient
from azure.core.credentials import AzureKeyCredential

def extract_expenses_from_invoice(invoice_file_path: str) -> dict:
    endpoint = "https://<your-endpoint>.cognitiveservices.azure.com/"
    key = "<your-key>"
    credential = AzureKeyCredential(key)
    client = DocumentAnalysisClient(endpoint=endpoint, credential=credential)

    document = client.begin_analyze_document(invoice_file_path).result()

    fields = document.read_results[0].fields

    expense_data = {
        "total_amount": None,
        "tax_amount": None,
        "subtotal_amount": None,
        "payment_terms": None,
        "due_date": None,
        "vendor_name": None,
        "items": []
    }

    for field in fields:
        if field.name == "Total Amount":
            expense_data["total_amount"] = field.value
        elif field.name == "Tax Amount":
            expense_data["tax_amount"] = field.value
        elif field.name == "Subtotal Amount":
            expense_data["subtotal_amount"] = field.value
        elif field.name == "Payment Terms":
            expense_data["payment_terms"] = field.value
        elif field.name == "Due Date":
            expense_data["due_date"] = field.value
        elif field.name == "Vendor Name":
            expense_data["vendor_name"] = field.value
        elif field.name == "Item":
            item = {
                "description": field.value,
                "quantity": None,
                "unit_price": None,
                "total_price": None
            }
            if field.value_details:
                for detail in field.value_details:
                    if detail.name == "Quantity":
                        item["quantity"] = detail.value
                    elif detail.name == "Unit Price":
                        item["unit_price"] = detail.value
                    elif detail.name == "Total Price":
                        item["total_price"] = detail.value
            expense_data["items"].append(item)

    return expense_data

